mapper.select:
SELECT * FROM CHAT_MESSAGE
WHERE ROOM_ID = #{roomId}
ORDER BY SENT_AT ASC

mapper.update:
UPDATE CHAT_MESSAGE
SET IS_READ = 'Y'
WHERE ROOM_ID = #{roomId}
  AND RECEIVER_NO = #{userNo}
  AND IS_READ = 'N'

mapper.select:
SELECT COUNT(*)
FROM CHAT_MESSAGE
WHERE ROOM_ID = #{roomId}
  AND SENDER_NO = #{userNo}
  AND IS_READ = 'N'
